const sourceName = $json.body?.source_name || 'csv_pipeline_import';
const provider = $json.body?.provider || 'mock';
const csvContent = $json.body?.csv_content || '';

function splitCsvLine(line) {
  const values = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    const nextChar = line[i + 1];
    if (char === '"') {
      if (inQuotes && nextChar === '"') {
        current += '"';
        i += 1;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }
    if (char === ',' && !inQuotes) {
      values.push(current);
      current = '';
      continue;
    }
    current += char;
  }
  values.push(current);
  return values;
}

function normalizeHeader(header) {
  return String(header || '').trim().toLowerCase().replace(/ /g, '_').replace(/-/g, '_');
}

const lines = csvContent.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
if (lines.length < 2) {
  return [{ json: { source_name: sourceName, provider, items: [] } }];
}

const headers = splitCsvLine(lines[0]).map(normalizeHeader);
const items = lines.slice(1).map((line) => {
  const values = splitCsvLine(line);
  const row = {};
  headers.forEach((header, index) => {
    row[header] = (values[index] || '').trim();
  });
  const attachedDocuments = String(row.attached_documents || row.documents || row.pieces_jointes || '')
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean);
  return {
    source_file: sourceName,
    channel: ['email', 'telephone', 'courrier', 'portail'].includes((row.channel || '').toLowerCase()) ? row.channel.toLowerCase() : 'email',
    customer_id: row.customer_id || row.client_id || null,
    contract_id: row.contract_id || row.case_id || row.dossier_id || row.claim_id || null,
    provider,
    claim_text: row.claim_text || row.message || row.description || '',
    attached_documents: attachedDocuments
  };
});

return [{ json: { source_name: sourceName, provider, items } }];
